mapper.insert:
/** com.khnp.pels.api.TstStrokeInsert */
INSERT
  INTO GE_MP_CHECK_STRK_S
     (
       TST_UNQ_KY_VAL
     , PAGE_NO
     , STROKE_SEQ
     , POINT_PATH
     , STROKE_COLOR
     , STROKE_WIDTH
     , CREPR_ID
     , CRE_DT

     , DLT_YN
     , DLTPR_ID
     , DLT_DT

     )
VALUES
     (
       #{TST_UNQ_KY_VAL}
     , #{PAGE_NO}
     , #{STROKE_SEQ}
     , #{POINT_PATH, jdbcType=BLOB}
     , #{STROKE_COLOR}
     , #{STROKE_WIDTH}
     , #{CREPR_ID}
     , TO_TIMESTAMP(#{CRE_DT},'YYYY-MM-DD"T"HH24:MI:SS.FF3')

     , 'Y'
     , #{DLTPR_ID, jdbcType=VARCHAR}
     , TO_TIMESTAMP(#{DLT_DT},'YYYY-MM-DD"T"HH24:MI:SS.FF3')

     )

mapper.update:
/** com.khnp.pels.api.TstStrokeUpdateForDelete */
UPDATE GE_MP_CHECK_STRK_S
   SET DLT_YN = 'Y'
     , DLTPR_ID = #{DLTPR_ID}
     , DLT_DT = TO_TIMESTAMP(#{DLT_DT},'YYYY-MM-DD"T"HH24:MI:SS.FF3')
WHERE TST_UNQ_KY_VAL = #{TST_UNQ_KY_VAL}
  AND PAGE_NO = #{PAGE_NO}
  AND STROKE_SEQ = #{STROKE_SEQ}
  AND DLT_YN = 'N'
